int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||(string(argv[1])!="--config"&&string(argv[1])!="--check-config")){fprintf(stderr,"usage: server --config PATH\n");return 1;}try{Config cfg=build(argv[2]);if(string(argv[1])=="--check-config")return 0;for(auto&e:cfg.endpoints){e.fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);int yes=1;setsockopt(e.fd,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));sockaddr_in a{};a.sin_family=AF_INET;a.sin_port=htons(e.port);inet_pton(AF_INET,"127.0.0.1",&a.sin_addr);if(bind(e.fd,(sockaddr*)&a,sizeof(a))||listen(e.fd,1024))throw runtime_error("cannot bind listener");}signal(SIGTERM,sig);signal(SIGINT,sig);signal(SIGCHLD,sig);signal(SIGHUP,sig);set<pid_t> children;auto spawn=[&](){pid_t p=fork();if(p==0){stopflag=0;worker(cfg);}if(p>0)children.insert(p);};for(int i=0;i<cfg.workers;i++)spawn();while(!stopflag){if(childflag){childflag=0;int status;pid_t p;while((p=waitpid(-1,&status,WNOHANG))>0){children.erase(p);if(!stopflag)spawn();}}if(reloadflag){reloadflag=0;}usleep(50000);}for(auto&e:cfg.endpoints)close(e.fd);for(pid_t p:children)kill(p,SIGTERM);while(waitpid(-1,nullptr,0)>0){}return 0;}catch(const exception&e){fprintf(stderr,"config: %s\n",e.what());return 1;}}
